(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,bar=document.querySelector('.project-bar');if(!bar)return;const key='hvacstudio:backup-reminder:v1',box=document.createElement('div');box.className='backup-reminder';box.hidden=true;box.setAttribute('role','status');box.innerHTML='<span>'+L('Dự án đang lưu trên trình duyệt này. Xóa dữ liệu trình duyệt hoặc đổi máy có thể làm bạn mất quyền truy cập dữ liệu. Hãy xuất file JSON và giữ bản sao ở nơi an toàn.','Projects are stored in this browser. Clearing browser data or changing devices may make this data unavailable. Export JSON and keep a copy in a safe location.')+'</span><div><button type="button" data-backup-export>'+L('Sao lưu ngay','Back up now')+'</button><button type="button" data-backup-later>'+L('Nhắc lại ngày mai','Remind me tomorrow')+'</button></div>';(bar.querySelector('#project-content')||bar).append(box);
const read=()=>{try{return JSON.parse(localStorage.getItem(key))||{};}catch{return {};}},write=v=>{try{localStorage.setItem(key,JSON.stringify(v));}catch{}};
function refresh(){let db;try{db=JSON.parse(localStorage.getItem('hvacstudio:projects:v1'));}catch{}const projects=(db?.projects||[]).filter(p=>!p.deletedAt),count=projects.reduce((s,p)=>s+Object.keys(p.tools||{}).length+(p.fabricationSegments?.length||0)+(p.supportSegments?.length||0)+Object.values(p.itemLists||{}).reduce((n,a)=>n+a.length,0)+Object.values(p.segmentLists||{}).reduce((n,a)=>n+a.length,0),0),v=read(),now=Date.now();if(count&&!v.first){v.first=now;write(v);}box.hidden=!(count&&(count>=5||now-(v.first||now)>=7*864e5)&&now>(v.snooze||0)&&(!v.exportRequested||now-v.exportRequested>=7*864e5));}
box.querySelector('[data-backup-export]').onclick=()=>bar.querySelector('[data-project=export]').click();box.querySelector('[data-backup-later]').onclick=()=>{write({...read(),snooze:Date.now()+864e5});refresh();};bar.addEventListener('click',e=>{if(e.target.closest('[data-project=export]')){write({...read(),exportRequested:Date.now()});refresh();}});document.addEventListener('hvac-project-ready',refresh);window.addEventListener('storage',refresh);let timer;document.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(refresh,1500);});document.addEventListener('click',()=>{clearTimeout(timer);timer=setTimeout(refresh,1500);});refresh();})();
